        ('everyday', 'story', 2, {'en': 'Local Football Match', 'pl': 'Mecz piłki nożnej'}, ['On Saturday the town team plays.', 'The score is one to one.', 'In the last minute they score.', 'The crowd cheers loudly.'], ['W sobotę gra drużyna z miasta.', 'Wynik to jeden do jednego.', 'W ostatniej minucie strzelają gola.', 'Kibice głośno wiwatują.'], ['On Saturday the town team plays.', 'The score is one to one.', 'In the last minute they score.', 'The crowd cheers loudly.'], [{'word': 'team', 'gloss': {'pl': 'drużyna', 'en': 'team'}, 'pos': 'noun'}, {'word': 'score', 'gloss': {'pl': 'wynik', 'en': 'score'}, 'pos': 'noun'}, {'word': 'crowd', 'gloss': {'pl': 'tłum', 'en': 'crowd'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'When is the match?', 'pl': 'Kiedy jest mecz?'}, 'acceptedAnswers': {'en': ['Saturday'], 'pl': ['w sobotę']}, 'explanation': {'en': 'It is on Saturday.', 'pl': 'Jest w sobotę.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'What is the final mood?', 'pl': 'Jaka jest atmosfera na końcu?'}, 'acceptedAnswers': {'en': ['cheering'], 'pl': ['wiwaty']}, 'explanation': {'en': 'The crowd cheers.', 'pl': 'Kibice wiwatują.'}}),
