        ('conversation', 'dialogue', 4, {'en': 'Noisy Neighbor', 'pl': 'Hałaśliwy sąsiad'}, ['"Excuse me, your music is very loud."', '"Sorry, we did not realize."', '"Could you lower it after ten?"', '"Of course, no problem."', '"Thank you for understanding."'], ['"Przepraszam, muzyka jest bardzo głośna."', '"Przepraszamy, nie zdawaliśmy sobie sprawy."', '"Czy możecie ściszyć po dziesiątej?"', '"Jasne, bez problemu."', '"Dziękuję za zrozumienie."'], ['"Excuse me, your music is very loud."', '"Sorry, we did not realize."', '"Could you lower it after ten?"', '"Of course, no problem."', '"Thank you for understanding."'], [{'word': 'neighbor', 'gloss': {'pl': 'sąsiad', 'en': 'neighbor'}, 'pos': 'noun'}, {'word': 'music', 'gloss': {'pl': 'muzyka', 'en': 'music'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'What is the problem?', 'pl': 'Jaki jest problem?'}, 'acceptedAnswers': {'en': ['loud music'], 'pl': ['głośna muzyka']}, 'explanation': {'en': 'The music is too loud.', 'pl': 'Muzyka jest zbyt głośna.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'After what time should they lower it?', 'pl': 'Po której godzinie mają ściszyć?'}, 'acceptedAnswers': {'en': ['ten'], 'pl': ['dziesiątej']}, 'explanation': {'en': "After ten o'clock.", 'pl': 'Po dziesiątej.'}}),
        ('everyday', 'story', 4, {'en': 'Shelter Volunteer', 'pl': 'Wolontariat w schronisku'}, ['Every Saturday I walk dogs at the shelter.', 'Today a shy greyhound arrives.', 'I sit quietly until she sniffs my hand.', 'We walk only fifty meters but she wags her tail.', 'A couple adopts her the next week.', 'I sign up for another month.'], ['W każdą sobotę wyprowadzam psy ze schroniska.', 'Dziś przyjeżdża nieśmiała chart.', 'Siedzę cicho, aż powącha moją dłoń.', 'Spacerujemy tylko pięćdziesiąt metrów, ale merda ogonem.', 'Para adoptuje ją w następnym tygodniu.', 'Zapisuję się na kolejny miesiąc.'], ['Every Saturday I walk dogs at the shelter.', 'Today a shy greyhound arrives.', 'I sit quietly until she sniffs my hand.', 'We walk only fifty meters but she wags her tail.', 'A couple adopts her the next week.', 'I sign up for another month.'], [{'word': 'shelter', 'gloss': {'pl': 'schronisko', 'en': 'shelter'}, 'pos': 'noun'}, {'word': 'greyhound', 'gloss': {'pl': 'chart', 'en': 'greyhound'}, 'pos': 'noun'}, {'word': 'adoption', 'gloss': {'pl': 'adopcja', 'en': 'adoption'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'Which dog arrives?', 'pl': 'Jaki pies przyjeżdża?'}, 'acceptedAnswers': {'en': ['greyhound'], 'pl': ['chart']}, 'explanation': {'en': 'A shy greyhound arrives.', 'pl': 'Przyjeżdża nieśmiały chart.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'What happens next week?', 'pl': 'Co dzieje się w następnym tygodniu?'}, 'acceptedAnswers': {'en': ['adoption'], 'pl': ['adopcja']}, 'explanation': {'en': 'A couple adopts her.', 'pl': 'Para ją adoptuje.'}}),
        ('conversation', 'story', 4, {'en': 'Language Exchange', 'pl': 'Wymiana językowa'}, ['I meet Rosa at a language café.', 'She wants Polish phrases for travel.', 'I want confidence speaking Spanish.', 'We switch languages every fifteen minutes.', 'A waiter joins and corrects our accents.', 'We exchange numbers and plan next Tuesday.'], ['Spotykam Rosę w kawiarni językowej.', 'Ona chce polskich zwrotów na podróż.', 'Ja chcę pewności w hiszpańskim.', 'Co piętnaście minut zmieniamy języki.', 'Kelner dołącza i poprawia akcent.', 'Wymieniamy numery i umawiamy się na wtorek.'], ['I meet Rosa at a language café.', 'She wants Polish phrases for travel.', 'I want confidence speaking Spanish.', 'We switch languages every fifteen minutes.', 'A waiter joins and corrects our accents.', 'We exchange numbers and plan next Tuesday.'], [{'word': 'exchange', 'gloss': {'pl': 'wymiana', 'en': 'exchange'}, 'pos': 'noun'}, {'word': 'phrase', 'gloss': {'pl': 'zwrot', 'en': 'phrase'}, 'pos': 'noun'}, {'word': 'accent', 'gloss': {'pl': 'akcent', 'en': 'accent'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'How often do they switch languages?', 'pl': 'Jak często zmieniają języki?'}, 'acceptedAnswers': {'en': ['every fifteen minutes'], 'pl': ['co piętnaście minut']}, 'explanation': {'en': 'They switch every fifteen minutes.', 'pl': 'Zmieniają co piętnaście minut.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'When is the next meeting?', 'pl': 'Kiedy następne spotkanie?'}, 'acceptedAnswers': {'en': ['Tuesday'], 'pl': ['we wtorek']}, 'explanation': {'en': 'They plan next Tuesday.', 'pl': 'Umawiają się na wtorek.'}}),
