        ('workplace', 'story', 6, {'en': 'Ethical Dilemma', 'pl': 'Dylemat etyczny'}, ['A supplier offers a hidden discount for quick approval.', 'My manager asks me to sign today.', 'The discount violates company policy.', 'I request time to consult compliance.', 'Compliance confirms the risk of fraud.', 'We choose a slower but honest negotiation.', 'The supplier eventually accepts standard terms.'], ['Dostawca oferuje ukrytą zniżkę za szybką akceptację.', 'Szef prosi o podpis dziś.', 'Zniżka łamie politykę firmy.', 'Proszę o czas na konsultację z compliance.', 'Compliance potwierdza ryzyko oszustwa.', 'Wybieramy wolniejsze, uczciwe negocjacje.', 'Dostawca ostatecznie akceptuje standardowe warunki.'], ['A supplier offers a hidden discount for quick approval.', 'My manager asks me to sign today.', 'The discount violates company policy.', 'I request time to consult compliance.', 'Compliance confirms the risk of fraud.', 'We choose a slower but honest negotiation.', 'The supplier eventually accepts standard terms.'], [{'word': 'supplier', 'gloss': {'pl': 'dostawca', 'en': 'supplier'}, 'pos': 'noun'}, {'word': 'policy', 'gloss': {'pl': 'polityka', 'en': 'policy'}, 'pos': 'noun'}, {'word': 'fraud', 'gloss': {'pl': 'oszustwo', 'en': 'fraud'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'What violates policy?', 'pl': 'Co łamie politykę?'}, 'acceptedAnswers': {'en': ['hidden discount'], 'pl': ['ukryta zniżka']}, 'explanation': {'en': 'The hidden discount violates policy.', 'pl': 'Ukryta zniżka łamie politykę.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'Who confirms fraud risk?', 'pl': 'Kto potwierdza ryzyko oszustwa?'}, 'acceptedAnswers': {'en': ['compliance'], 'pl': ['compliance']}, 'explanation': {'en': 'Compliance confirms it.', 'pl': 'Compliance to potwierdza.'}}),
        ('travel', 'story', 5, {'en': 'Immigration Interview', 'pl': 'Rozmowa imigracyjna'}, ['I arrive early at the consulate with a folder of papers.', 'Security scans my bag and keeps my phone.', 'The officer asks about my job and housing plans.', 'I answer clearly and show bank statements.', 'She stamps a document and explains next steps.', 'Outside, rain falls but I feel relief.'], ['Jadę wcześnie do konsulatu z teczką papierów.', 'Ochrona skanuje torbę i zatrzymuje telefon.', 'Urzędnik pyta o pracę i plany mieszkaniowe.', 'Odpowiadam jasno i pokazuję wyciągi bankowe.', 'Stawia pieczęć i tłumaczy kolejne kroki.', 'Na zewnątrz pada deszcz, ale czuję ulgę.'], ['I arrive early at the consulate with a folder of papers.', 'Security scans my bag and keeps my phone.', 'The officer asks about my job and housing plans.', 'I answer clearly and show bank statements.', 'She stamps a document and explains next steps.', 'Outside, rain falls but I feel relief.'], [{'word': 'consulate', 'gloss': {'pl': 'konsulat', 'en': 'consulate'}, 'pos': 'noun'}, {'word': 'stamp', 'gloss': {'pl': 'pieczęć', 'en': 'stamp'}, 'pos': 'noun'}, {'word': 'statement', 'gloss': {'pl': 'wyciąg', 'en': 'statement'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'What does security keep?', 'pl': 'Co zatrzymuje ochrona?'}, 'acceptedAnswers': {'en': ['phone'], 'pl': ['telefon']}, 'explanation': {'en': 'They keep the phone.', 'pl': 'Zatrzymują telefon.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'How does the narrator feel outside?', 'pl': 'Jak czuje się narrator na zewnątrz?'}, 'acceptedAnswers': {'en': ['relief'], 'pl': ['ulga']}, 'explanation': {'en': 'They feel relief.', 'pl': 'Czuje ulgę.'}}),
        ('qa', 'story', 6, {'en': 'Climate Panel Debate', 'pl': 'Debata klimatyczna'}, ['Experts gather for a televised climate panel.', 'One scientist presents ice-core data.', 'A mayor describes flooded streets in her city.', 'A student asks why action feels slow.', 'Panelists disagree on carbon taxes but agree on urgency.', 'Viewers submit questions through an app.', 'The host ends with a call for local projects.'], ['Eksperci zbierają się na telewizyjny panel klimatyczny.', 'Jeden naukowiec prezentuje dane z rdzeni lodowych.', 'Burmistrz opisuje zalane ulice w swoim mieście.', 'Student pyta, dlaczego działania są wolne.', 'Paneliści spierają się o podatki węglowe, ale zgadzają się co do pilności.', 'Widzowie wysyłają pytania przez aplikację.', 'Prowadzący kończy wezwaniem do lokalnych projektów.'], ['Experts gather for a televised climate panel.', 'One scientist presents ice-core data.', 'A mayor describes flooded streets in her city.', 'A student asks why action feels slow.', 'Panelists disagree on carbon taxes but agree on urgency.', 'Viewers submit questions through an app.', 'The host ends with a call for local projects.'], [{'word': 'panel', 'gloss': {'pl': 'panel', 'en': 'panel'}, 'pos': 'noun'}, {'word': 'carbon tax', 'gloss': {'pl': 'podatek węglowy', 'en': 'carbon tax'}, 'pos': 'noun'}, {'word': 'urgency', 'gloss': {'pl': 'pilność', 'en': 'urgency'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'What data is presented?', 'pl': 'Jakie dane są prezentowane?'}, 'acceptedAnswers': {'en': ['ice-core data'], 'pl': ['dane z rdzeni lodowych']}, 'explanation': {'en': 'Ice-core data is shown.', 'pl': 'Prezentowane są dane z rdzeni lodowych.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'What do they agree on?', 'pl': 'W czym się zgadzają?'}, 'acceptedAnswers': {'en': ['urgency'], 'pl': ['pilność']}, 'explanation': {'en': 'They agree on urgency.', 'pl': 'Zgadzają się co do pilności.'}}),
        ('workplace', 'story', 6, {'en': 'Startup Pitch', 'pl': 'Prezentacja startupu'}, ['Two founders enter a glass office for a pitch.', 'Their slide deck crashes on the projector.', 'Instead they tell a story about a farmer losing crops.', 'Investors lean forward and ask about scalability.', 'One investor offers a small seed round with mentorship.', 'Founders leave with homework, not champagne.'], ['Dwóch założycieli wchodzi do szklanej sali na pitch.', 'Prezentacja pada na projektorze.', 'Zamiast tego opowiadają historię rolnika tracącego plony.', 'Inwestorzy pochylają się i pytają o skalowalność.', 'Jeden inwestor oferuje małą rundę seed z mentorem.', 'Wychodzą z zadaniami, nie z szampanem.'], ['Two founders enter a glass office for a pitch.', 'Their slide deck crashes on the projector.', 'Instead they tell a story about a farmer losing crops.', 'Investors lean forward and ask about scalability.', 'One investor offers a small seed round with mentorship.', 'Founders leave with homework, not champagne.'], [{'word': 'pitch', 'gloss': {'pl': 'prezentacja', 'en': 'pitch'}, 'pos': 'noun'}, {'word': 'investor', 'gloss': {'pl': 'inwestor', 'en': 'investor'}, 'pos': 'noun'}, {'word': 'scalability', 'gloss': {'pl': 'skalowalność', 'en': 'scalability'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'What fails during the pitch?', 'pl': 'Co zawodzi podczas pitchu?'}, 'acceptedAnswers': {'en': ['slide deck'], 'pl': ['prezentacja']}, 'explanation': {'en': 'The slide deck crashes.', 'pl': 'Prezentacja pada.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'What do they leave with?', 'pl': 'Z czym wychodzą?'}, 'acceptedAnswers': {'en': ['homework'], 'pl': ['zadaniami']}, 'explanation': {'en': 'They leave with homework.', 'pl': 'Wychodzą z zadaniami.'}}),
